package com.example.myfitnesstracker;

import android.app.*;import android.os.Bundle;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

public class MainActivity extends Activity {
  final int BLACK=Color.rgb(17,17,17), GREY=Color.rgb(242,242,242), MID=Color.rgb(115,115,115), WHITE=Color.WHITE;
  LinearLayout root, body, nav; DB db; String page="Home"; YearMonth shownMonth=YearMonth.now();
  public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(WHITE);getWindow().setNavigationBarColor(WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);db=new DB(this);render();}
  int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);} 
  GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(18));if(stroke>0)d.setStroke(dp(1),stroke);return d;}
  TextView text(String s,int size,boolean bold,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
  LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
  LinearLayout horizontal(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
  void pad(View v,int a){v.setPadding(dp(a),dp(a),dp(a),dp(a));}
  void render(){root=vertical();root.setBackgroundColor(WHITE);setContentView(root);LinearLayout header=vertical();header.setPadding(dp(22),dp(18),dp(22),dp(10));TextView brand=text("MY FITNESS TRACKER",12,true,MID);LinearLayout brandRow=horizontal();ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_logo);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(28),dp(28));lp.setMargins(0,0,dp(10),0);brandRow.addView(logo,lp);brandRow.addView(brand);header.addView(brandRow);TextView title=text(page,28,true,BLACK);title.setPadding(0,dp(5),0,0);header.addView(title);root.addView(header);ScrollView scroll=new ScrollView(this);body=vertical();body.setPadding(dp(18),dp(8),dp(18),dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(page.equals("Home"))home();else if(page.equals("Habits"))habits();else if(page.equals("Statistics"))stats();else settings();nav=horizontal();nav.setBackgroundColor(WHITE);nav.setPadding(dp(5),dp(8),dp(5),dp(8));String[] tabs={"Home","Habits","Statistics","Settings"};for(String s:tabs){TextView t=text((s.equals("Home")?"⌂":s.equals("Habits")?"✓":s.equals("Statistics")?"▥":"⚙")+"\n"+s,11,page.equals(s),page.equals(s)?BLACK:MID);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(5),0,dp(5));nav.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));t.setOnClickListener(v->{page=s;render();});}root.addView(nav);}
  void section(String title){TextView t=text(title,17,true,BLACK);t.setPadding(dp(2),dp(16),0,dp(10));body.addView(t);}
  LinearLayout card(){LinearLayout c=vertical();c.setPadding(dp(17),dp(15),dp(17),dp(15));c.setBackground(shape(GREY,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(11);body.addView(c,p);return c;}
  TextView button(String label,boolean dark,Runnable r){TextView b=text(label,14,true,dark?WHITE:BLACK);b.setGravity(Gravity.CENTER);b.setPadding(dp(16),dp(13),dp(16),dp(13));b.setBackground(shape(dark?BLACK:WHITE,dark?BLACK:Color.LTGRAY));b.setOnClickListener(v->r.run());return b;}
  void addButton(String label,boolean dark,Runnable r){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);body.addView(button(label,dark,r),p);}
  String today(){return LocalDate.now().toString();} boolean restSunday(){return getPreferences(0).getBoolean("sundayRest",false);} 
  boolean scheduled(Cursor c,LocalDate date){if(date.isBefore(LocalDate.parse(c.getString(c.getColumnIndexOrThrow("start_date")))))return false;if(restSunday()&&date.getDayOfWeek()==DayOfWeek.SUNDAY)return false;String sch=c.getString(c.getColumnIndexOrThrow("schedule"));if(sch.equals("daily"))return true;return Arrays.asList(sch.split(",")).contains(String.valueOf(date.getDayOfWeek().getValue()));}
  Cursor all(){return db.getReadableDatabase().rawQuery("SELECT * FROM habits ORDER BY id DESC",null);} boolean done(int id,LocalDate d){Cursor c=db.getReadableDatabase().rawQuery("SELECT 1 FROM checkins WHERE habit_id=? AND day=?",new String[]{""+id,d.toString()});boolean b=c.moveToFirst();c.close();return b;}
  int habitCount(LocalDate d){int n=0;Cursor c=all();while(c.moveToNext())if(scheduled(c,d))n++;c.close();return n;} int completedCount(LocalDate d){int n=0;Cursor c=all();while(c.moveToNext())if(scheduled(c,d)&&done(c.getInt(0),d))n++;c.close();return n;}
  void home(){LocalDate d=LocalDate.now();int total=habitCount(d),done=completedCount(d),pct=total==0?0:done*100/total;TextView date=text(d.format(DateTimeFormatter.ofPattern("EEEE, d MMMM yyyy")),14,false,MID);body.addView(date);LinearLayout c=card();c.setBackground(shape(BLACK,0));c.addView(text("TODAY'S PROGRESS",12,true,Color.LTGRAY));TextView p=text(pct+"%",42,true,WHITE);p.setPadding(0,dp(7),0,dp(2));c.addView(p);c.addView(text(done+" completed  ·  "+Math.max(0,total-done)+" remaining",14,false,Color.LTGRAY));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(pct);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(WHITE));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff555555));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(6));bp.topMargin=dp(14);c.addView(bar,bp);section("Today's habits");Cursor cur=all();boolean any=false;while(cur.moveToNext()){if(!scheduled(cur,d))continue;any=true;int id=cur.getInt(0);String name=cur.getString(1);boolean checked=done(id,d);LinearLayout row=horizontal();row.setPadding(dp(12),dp(7),dp(8),dp(7));row.setBackground(shape(GREY,0));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(8);body.addView(row,rp);CheckBox cb=new CheckBox(this);cb.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{BLACK,MID}));cb.setChecked(checked);row.addView(cb);TextView nm=text(name,15,true,BLACK);row.addView(nm,new LinearLayout.LayoutParams(0,-2,1));cb.setOnCheckedChangeListener((v,is)->{db.getWritableDatabase().execSQL(is?"INSERT OR IGNORE INTO checkins(habit_id,day) VALUES(?,?)":"DELETE FROM checkins WHERE habit_id=? AND day=?",new Object[]{id,d.toString()});render();});nm.setOnClickListener(v->details(id));}cur.close();if(!any)body.addView(text(total==0?"No habits yet. Add your first habit to get started.":"No habits scheduled for today. Enjoy your rest day!",14,false,MID));addButton("＋  Add a habit",true,()->habitDialog(-1));section("Quick overview");LinearLayout stats=card();stats.addView(text("Current streaks are calculated per habit from saved check-ins.",14,false,MID));stats.addView(text("Scheduled today: "+total+"     Completed: "+done,15,true,BLACK));addButton("View monthly statistics  →",false,()->{page="Statistics";render();});}
  void habits(){addButton("＋  Create custom habit",true,()->habitDialog(-1));Cursor c=all();if(c.getCount()==0){body.addView(text("Your habit list is empty. Create a habit with your own name and schedule.",14,false,MID));}while(c.moveToNext()){int id=c.getInt(0);String name=c.getString(1),sch=c.getString(2);LinearLayout box=card();LinearLayout r=horizontal();box.addView(r);TextView n=text(name,17,true,BLACK);r.addView(n,new LinearLayout.LayoutParams(0,-2,1));TextView more=text("•••",20,true,BLACK);r.addView(more);more.setPadding(dp(12),dp(4),dp(5),dp(4));more.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"View details & history","Edit habit","Delete habit"},(di,w)->{if(w==0)details(id);if(w==1)habitDialog(id);if(w==2)deleteHabit(id,name);}).show());box.addView(text(sch.equals("daily")?"Every day":"Selected weekdays: "+sch,12,false,MID));box.addView(text("Started "+c.getString(3),12,false,MID));}c.close();}
  void habitDialog(int id){String oldName="",oldSch="daily",oldStart=today();if(id!=-1){Cursor c=db.getReadableDatabase().rawQuery("SELECT * FROM habits WHERE id=?",new String[]{""+id});if(c.moveToFirst()){oldName=c.getString(1);oldSch=c.getString(2);oldStart=c.getString(3);}c.close();}final String initialName=oldName,initialSch=oldSch,initialStart=oldStart;LinearLayout form=vertical();form.setPadding(dp(20),dp(5),dp(20),0);EditText name=new EditText(this);name.setSingleLine();name.setHint("Habit name (e.g. Read 10 pages)");name.setText(initialName);form.addView(name);RadioGroup rg=new RadioGroup(this);rg.setOrientation(RadioGroup.VERTICAL);RadioButton daily=new RadioButton(this);daily.setText("Every day");daily.setId(1);rg.addView(daily);RadioButton custom=new RadioButton(this);custom.setText("Choose weekdays");custom.setId(2);rg.addView(custom);daily.setChecked(initialSch.equals("daily"));custom.setChecked(!initialSch.equals("daily"));form.addView(rg);LinearLayout days=horizontal();CheckBox[] checks=new CheckBox[7];String[] labels={"M","T","W","T","F","S","S"};for(int i=0;i<7;i++){checks[i]=new CheckBox(this);checks[i].setText(labels[i]);checks[i].setTextSize(11);checks[i].setPadding(0,0,0,0);checks[i].setChecked(initialSch.equals("daily")||Arrays.asList(initialSch.split(",")).contains(""+(i+1)));days.addView(checks[i],new LinearLayout.LayoutParams(0,-2,1));}form.addView(days);EditText start=new EditText(this);start.setSingleLine();start.setHint("Start date: YYYY-MM-DD");start.setText(initialStart);form.addView(start);EditText reminder=new EditText(this);reminder.setSingleLine();reminder.setHint("Reminder time optional (HH:MM)");form.addView(reminder);new AlertDialog.Builder(this).setTitle(id==-1?"Add habit":"Edit habit").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",(di,w)->{String nm=name.getText().toString().trim(),sd=start.getText().toString().trim(),schedule="";if(nm.isEmpty()){toast("Please enter a habit name.");return;}try{LocalDate.parse(sd);}catch(Exception e){toast("Enter a valid start date as YYYY-MM-DD.");return;}if(rg.getCheckedRadioButtonId()==1)schedule="daily";else{for(int i=0;i<7;i++)if(checks[i].isChecked())schedule+=(schedule.isEmpty()?"":",")+(i+1);if(schedule.isEmpty()){toast("Choose at least one weekday.");return;}}SQLiteDatabase wdb=db.getWritableDatabase();if(id==-1){wdb.execSQL("INSERT INTO habits(name,schedule,start_date,reminder) VALUES(?,?,?,?)",new Object[]{nm,schedule,sd,reminder.getText().toString().trim()});}else{wdb.execSQL("UPDATE habits SET name=?,schedule=?,start_date=?,reminder=? WHERE id=?",new Object[]{nm,schedule,sd,reminder.getText().toString().trim(),id});}render();}).show();}
  void deleteHabit(int id,String name){new AlertDialog.Builder(this).setTitle("Delete habit?").setMessage("Delete ‘"+name+"’ and its saved check-in history? This cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{db.getWritableDatabase().execSQL("DELETE FROM checkins WHERE habit_id=?",new Object[]{id});db.getWritableDatabase().execSQL("DELETE FROM habits WHERE id=?",new Object[]{id});render();}).show();}
  void details(int id){Cursor c=db.getReadableDatabase().rawQuery("SELECT * FROM habits WHERE id=?",new String[]{""+id});if(!c.moveToFirst()){c.close();return;}String name=c.getString(1);c.close();page="Habit Details";render();LinearLayout box=card();box.addView(text(name,22,true,BLACK));LocalDate now=LocalDate.now();int total=0,done=0;StringBuilder hist=new StringBuilder();for(int i=0;i<30;i++){LocalDate d=now.minusDays(i);Cursor hc=db.getReadableDatabase().rawQuery("SELECT * FROM habits WHERE id=?",new String[]{""+id});if(hc.moveToFirst()&&scheduled(hc,d)){total++;boolean ok=done(id,d);if(ok)done++;hist.append(d.format(DateTimeFormatter.ofPattern("EEE, d MMM"))).append(ok?"   ✓ Completed":"   – Missed").append("\n");}hc.close();}int pct=total==0?0:done*100/total;box.addView(text("Last 30 days: "+done+" / "+total+" scheduled check-ins ("+pct+"%)",14,false,MID));box.addView(text("Current streak: "+streak(id,false)+" days",15,true,BLACK));box.addView(text("Longest streak: "+streak(id,true)+" days",15,true,BLACK));section("Recent history");body.addView(text(hist.length()==0?"No scheduled check-ins yet.":hist.toString(),14,false,BLACK));addButton("Edit habit",false,()->habitDialog(id));addButton("Back to habits",true,()->{page="Habits";render();});}
  int streak(int id,boolean longest){Cursor h=db.getReadableDatabase().rawQuery("SELECT * FROM habits WHERE id=?",new String[]{""+id});if(!h.moveToFirst()){h.close();return 0;}LocalDate start=LocalDate.parse(h.getString(3));h.close();LocalDate end=LocalDate.now();int run=0,best=0;boolean started=false;for(LocalDate d=start;!d.isAfter(end);d=d.plusDays(1)){Cursor hc=db.getReadableDatabase().rawQuery("SELECT * FROM habits WHERE id=?",new String[]{""+id});boolean sch=hc.moveToFirst()&&scheduled(hc,d);hc.close();if(!sch)continue;if(done(id,d)){run++;best=Math.max(best,run);started=true;}else{if(!longest)run=0;else run=0;} }if(longest)return best; // Current streak may end yesterday if today isn't completed yet.
    LocalDate d=LocalDate.now();Cursor hc=db.getReadableDatabase().rawQuery("SELECT * FROM habits WHERE id=?",new String[]{""+id});boolean todayScheduled=hc.moveToFirst()&&scheduled(hc,d);hc.close();if(todayScheduled&&!done(id,d))d=d.minusDays(1);run=0;for(;!d.isBefore(start);d=d.minusDays(1)){hc=db.getReadableDatabase().rawQuery("SELECT * FROM habits WHERE id=?",new String[]{""+id});boolean sch=hc.moveToFirst()&&scheduled(hc,d);hc.close();if(!sch)continue;if(done(id,d))run++;else break;}return run;}
  void stats(){LinearLayout controls=horizontal();controls.addView(button("‹",false,()->{shownMonth=shownMonth.minusMonths(1);render();}),new LinearLayout.LayoutParams(dp(48),dp(44)));TextView m=text(shownMonth.format(DateTimeFormatter.ofPattern("MMMM yyyy")),17,true,BLACK);m.setGravity(Gravity.CENTER);controls.addView(m,new LinearLayout.LayoutParams(0,dp(44),1));controls.addView(button("›",false,()->{if(shownMonth.isBefore(YearMonth.now())){shownMonth=shownMonth.plusMonths(1);render();}}),new LinearLayout.LayoutParams(dp(48),dp(44)));body.addView(controls);int poss=0,done=0;Map<Integer,int[]> per=new LinkedHashMap<>();Cursor c=all();while(c.moveToNext()){int id=c.getInt(0);per.put(id,new int[]{0,0});LocalDate st=LocalDate.parse(c.getString(3));LocalDate end=shownMonth.atEndOfMonth();if(end.isAfter(LocalDate.now()))end=LocalDate.now();for(LocalDate d=shownMonth.atDay(1);!d.isAfter(end);d=d.plusDays(1)){if(!d.isBefore(st)&&scheduled(c,d)){poss++;per.get(id)[1]++;if(done(id,d)){done++;per.get(id)[0]++;}}}}c.close();int pct=poss==0?0:done*100/poss;LinearLayout box=card();box.addView(text("MONTHLY COMPLETION",12,true,MID));box.addView(text(pct+"%",40,true,BLACK));box.addView(text(done+" completed  ·  "+(poss-done)+" missed",14,false,MID));box.addView(text(done+" / "+poss+" possible check-ins",14,true,BLACK));ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setMax(100);p.setProgress(pct);p.setProgressTintList(android.content.res.ColorStateList.valueOf(BLACK));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(7));pp.topMargin=dp(12);box.addView(p,pp);section("By habit");Cursor hc=all();if(!hc.moveToFirst())body.addView(text("No habits to calculate yet. Add a habit and your real stats will appear here.",14,false,MID));else do{int id=hc.getInt(0);int[] v=per.get(id);int q=v==null?0:v[1],z=v==null?0:v[0];LinearLayout item=card();item.addView(text(hc.getString(1),16,true,BLACK));item.addView(text((q==0?0:z*100/q)+"%  ·  "+z+" / "+q+" completed",13,false,MID));}while(hc.moveToNext());hc.close();}
  void settings(){section("Preferences");LinearLayout c=card();Switch sw=new Switch(this);sw.setText("Sunday rest mode");sw.setTextSize(15);sw.setTextColor(BLACK);sw.setChecked(restSunday());c.addView(sw);c.addView(text("When enabled, Sundays are excluded from scheduled check-ins and streaks.",12,false,MID));sw.setOnCheckedChangeListener((v,b)->{getPreferences(0).edit().putBoolean("sundayRest",b).apply();render();});section("Reminders");LinearLayout r=card();r.addView(text("Reminder times can be saved per habit when creating or editing it. Notifications are not scheduled in this build.",13,false,MID));section("Data & app");addButton("Reset all completion history",false,()->new AlertDialog.Builder(this).setTitle("Reset statistics?").setMessage("This removes all saved completion check-ins. Your habits and schedules will remain.").setNegativeButton("Cancel",null).setPositiveButton("Reset",(d,w)->{db.getWritableDatabase().execSQL("DELETE FROM checkins");render();}).show());LinearLayout about=card();about.addView(text("My Fitness Tracker",17,true,BLACK));about.addView(text("Version 1.0 · Offline-first habit tracking",13,false,MID));about.addView(text("Your habits and check-ins are stored locally on this phone.",13,false,MID));}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
  class DB extends SQLiteOpenHelper{DB(Context c){super(c,"fitness.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE habits(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,schedule TEXT NOT NULL,start_date TEXT NOT NULL,reminder TEXT DEFAULT '')");d.execSQL("CREATE TABLE checkins(habit_id INTEGER NOT NULL,day TEXT NOT NULL,PRIMARY KEY(habit_id,day),FOREIGN KEY(habit_id) REFERENCES habits(id))");}public void onUpgrade(SQLiteDatabase d,int o,int n){}}
}
